Object.assign(window.TEM8_DICTIONARY, {"electrons":{"oxford":{"phon":"ɪˈlektrɒn","pos":"noun","senses":[{"en":"a very small piece of matter (= a substance) with a negative electric charge, found in all atoms","cn":"电子"}]},"media":{"uk":"media/uk/electron__gb_1.mp3","us":"media/us/electron__us_1.mp3"}},"else":{"media":{"uk":"media/uk/else__gb_1.mp3","us":"media/us/else__us_1.mp3"},"oxford":{"phon":"els","pos":"adverb","senses":[{"en":"in addition to something already mentioned","cn":"其他的；别的","ex":{"en":"What else did he say?","cn":"他还说了些什么？"}},{"en":"different","cn":"另外的；不同的","ex":{"en":"Ask somebody else to help you.","cn":"另请个人来帮帮你吧。"}},{"en":"if not","cn":"要不然；否则","lab":"informal","ex":{"en":"Keep your mouth shut, else we'll be in trouble.","cn":"闭上你的嘴，否则我们会有麻烦的。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（用于anywhere，someone，what等词之后）其他的，别的","en":"You use else after words such as 'anywhere', 'someone', and 'what', to refer in a vague way to another person, place, or thing.","ex":{"en":"If I can't make a living at painting, at least I can teach someone else to paint","cn":"如果我不能靠画画谋生，至少我可以教别人画画。"}},{"pos":"ADJ 形容词","cn":"（用在everyone，everything，everywhere等词之后）其他的，别的","en":"You use else after words such as 'everyone', 'everything', and 'everywhere' to refer in a vague way to all the other people, things, or places except the one you are talking about.","ex":{"en":"As I try to be truthful, I expect everyone else to be truthful","cn":"既然我努力做到诚实，我希望其他所有人也能诚实。"}},{"pos":"PHR-CONJ-COORD","cn":"否则的话；要不然","en":"You use or else after stating a logical conclusion, to indicate that what you are about to say is evidence for that conclusion.","ex":{"en":"He must be a good plumber, or else he wouldn't be so busy","cn":"他肯定是个不错的管子工，要不然他不会那么忙。"}},{"pos":"PHR-CONJ-COORD","cn":"（引出不好的结果）否则，要不然","en":"You use or else to introduce a statement that indicates the unpleasant results that will occur if someone does or does not do something.","ex":{"en":"This time we really need to succeed or else people will start giving us funny looks","cn":"这次我们真的需要成功，否则人们会开始用异样的眼光看我们。"}},{"pos":"PHR-CONJ-COORD","cn":"（表示另外一种可能性）或者，还是，要不","en":"You use or else to introduce the second of two possibilities when you do not know which one is true.","ex":{"en":"You are either a total genius or else you must be absolutely raving mad","cn":"你要么是个不折不扣的天才，要么就是完全疯了。"}},{"pos":"PHRASE 短语","cn":"尤其;首先","en":"Above all else is used to emphasize that a particular thing is more important than other things.","ex":{"en":"Above all else I hate the cold.","cn":"我最讨厌寒冷。"}},{"pos":"PHRASE 短语","cn":"(表示威胁)否则的话，要不然的话","en":"You say 'or else' after a command to warn someone that if they do not obey, you will be angry and may harm or punish them.","ex":{"en":"Behave, or else!","cn":"规矩点，否则的话，哼！"}}]},"examples":[{"en":"I'm taking a few clothes and some books, not much else.","cn":"我带了几件衣服和一些书，别的就不多了。"},{"en":"Why didn't you come? Everybody else was there.","cn":"你为什么没来呢？其他所有的人都来了。"}]},"elephant":{"oxford":{"phon":"ˈelɪfənt","pos":"noun","senses":[{"en":"a very large animal with thick grey skin, large ears, two curved outer teeth called tusks and a long nose called a trunk. There are two types of elephant, the African and the Asian.","cn":"象","ex":{"en":"herds of elephants","cn":"象群"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"象","en":"An elephant is a very large animal with a long, flexible nose called a trunk, which it uses to pick up things. Elephants live in India and Africa."}]},"media":{"uk":"media/uk/elephant__gb_1.mp3","us":"media/us/elephant__us_1.mp3","img":["media/ldoce/img/elephant.jpg"]},"examples":[{"en":"The elephant in the room was the money that had to be paid in bribes.","cn":"难题明摆着，就是要付贿款。"},{"en":"herds of elephants/elephant herds","cn":"象群"}]},"electronic":{"media":{"uk":"media/uk/electronic__gb_1.mp3","us":"media/us/electronic__us_1.mp3"},"oxford":{"phon":"ɪˌlekˈtrɒnɪk","pos":"adjective","senses":[{"en":"having or using many small parts, such as microchips, that control and direct a small electric current","cn":"电子的；电子器件的","ex":{"en":"Airline passengers no longer have to turn off all electronic devices while on the plane.","cn":"航空公司乘客在飞机上不再需要关闭所有电子设备。"}},{"en":"done or produced by means of a computer or other electronic device","cn":"电子的；计算机的","ex":{"en":"electronic dance music","cn":"电子舞曲"}},{"en":"involving or connected with electronic equipment","cn":"电子设备的；电子器件的","ex":{"en":"an electronic engineer","cn":"电子工程师"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"电子的","en":"An electronic device has transistors or silicon chips which control and change the electric current passing through the device.","ex":{"en":"...expensive electronic equipment.","cn":"昂贵的电子设备"}},{"pos":"ADJ 形容词","cn":"电子化的;使用电子装置的","en":"An electronic process or activity involves the use of electronic devices.","ex":{"en":"...electronic surveillance.","cn":"电子监控"}}]},"examples":[{"en":"This dictionary is available in electronic form.","cn":"本词典有电子版本。"},{"en":"an electronic calculator","cn":"电子计算器"}]},"eliminate":{"media":{"uk":"media/uk/eliminate__gb_1.mp3","us":"media/us/eliminate__us_1.mp3"},"oxford":{"phon":"ɪˈlɪmɪneɪt","pos":"verb","senses":[{"en":"to remove or get rid of something","cn":"排除；清除；消除","ex":{"en":"Credit cards eliminate the need to carry a lot of cash.","cn":"有了信用卡就用不着携带很多现金。"}},{"en":"to stop considering that somebody/something might be responsible for something or chosen for something","cn":"排除；不再考虑","ex":{"en":"The police have eliminated two suspects from their investigation.","cn":"警方通过调查已经排除了两名嫌疑犯。"}},{"en":"to defeat a person or a team so that they no longer take part in a competition, etc.","cn":"（比赛中）淘汰","g":"[usually passive]","ex":{"en":"All the English teams were eliminated in the early stages of the competition.","cn":"所有英格兰队伍在比赛初期就被淘汰了。"}},{"en":"to kill somebody, especially an enemy or opponent","cn":"消灭，杀死（尤指敌人或对手）","lab":"formal","ex":{"en":"Most of the regime's opponents were eliminated.","cn":"该政权的大多数反对者都被消灭了。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"消除，剔除，根除(尤指不需要之物)","en":"To eliminate something, especially something you do not want or need, means to remove it completely.","ex":{"en":"The Sex Discrimination Act has not eliminated discrimination in employment","cn":"《反性别歧视法》并未根除工作中的歧视。"}},{"pos":"V-PASSIVE 被动动词","cn":"（在竞赛中）淘汰","en":"When a person or team is eliminated from a competition, they are defeated and so take no further part in the competition.","ex":{"en":"I was eliminated from the 400 metres in the semi-finals","cn":"我在400米半决赛中被淘汰。"}},{"pos":"VERB 动词","cn":"消灭;干掉","en":"If someone says that they have eliminated an enemy, they mean that they have killed them. By using the word 'eliminate', they are trying to make the action sound more positive than if they used the word 'kill'.","ex":{"en":"He declared war on the government and urged right-wingers to eliminate their opponents","cn":"他向政府宣战，并煽动右翼分子干掉他们的对手。"}}]},"examples":[{"en":"This diet claims to eliminate toxins from the body.","cn":"这种饮食据称具有排除体内毒素的作用。"},{"en":"The police have eliminated two suspects from their investigation.","cn":"警方通过调查已经排除了两名嫌疑犯。"}]},"elevated":{"media":{"uk":"media/uk/elevated__gb_1.mp3","us":"media/us/elevated__us_1.mp3"},"oxford":{"phon":"ˈelɪveɪtɪd","pos":"adjective","senses":[{"en":"high in rank","cn":"高贵的；职位高的","ex":{"en":"an elevated status","cn":"高贵的身份"}},{"en":"having a high moral or intellectual level","cn":"高尚的；睿智的","lab":"formal","ex":{"en":"elevated language/sentiments/thoughts","cn":"睿智的语言；高尚的情操；睿智的思想"}},{"en":"higher than the area around; above the level of the ground","cn":"高的；升高的；高出地面的","ex":{"en":"The house is in an elevated position, overlooking the town.","cn":"这栋房子地势较高，可以俯瞰全镇。"}},{"en":"higher than normal","cn":"偏高的","lab":"specialist","ex":{"en":"elevated blood pressure","cn":"血压偏高"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（人、工作、角色等）重要的，地位高的","en":"A person, job, or role that is elevated is very important or of very high rank.","ex":{"en":"His career has blossomed and that has given him a certain elevated status.","cn":"他的事业蓬勃发展，这在一定程度上提升了他的地位。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（想法、思想等）高尚的，崇高的,睿智的","en":"If thoughts or ideas are elevated, they are on a high moral or intellectual level.","ex":{"en":"...the magazine's elevated British tone.","cn":"杂志中高贵的英伦情调"}},{"pos":"ADJ 形容词","cn":"（土地、建筑等）高出周围的，高架的","en":"If land or buildings are elevated, they are raised up higher than the surrounding area.","ex":{"en":"An elevated platform on the stage collapsed during rehearsals.","cn":"在排练过程中舞台上垫高的一个平台塌了。"}}]},"examples":[{"en":"The house is in an elevated position, overlooking the town.","cn":"这栋房子地势较高，可以俯瞰全镇。"},{"en":"an elevated highway/railway/road (= one that runs on a bridge above the ground or street)","cn":"高架公路/铁路/道路"}]},"elt":{"oxford":{"phon":"ˌiː el ˈtiː","pos":"abbreviation","senses":[{"en":"English Language Teaching (the teaching of English to people for whom it is not the first language)","cn":"（对英语为非第一语言者的）英语教学"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（对英语为非第一语言者的）英语教学","en":"ELT is the teaching of English to people whose first language is not English. ELT is an abbreviation for (缩略=) 'English Language Teaching'."}]},"media":{"uk":"media/uk/elt__gb_1.mp3","us":"media/us/elt__us_1.mp3"}},"electromagnetic":{"oxford":{"phon":"ɪˌlektrəʊmæɡˈnetɪk","pos":"adjective","senses":[{"en":"having both electrical and magnetic characteristics (or properties)","cn":"电磁的","ex":{"en":"an electromagnetic wave/field","cn":"电磁波；电磁场"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"电磁能的;电磁效应的","en":"Electromagnetic is used to describe the electrical and magnetic forces or effects produced by an electric current.","ex":{"en":"...electromagnetic fields.","cn":"电磁场"}}]},"media":{"uk":"media/uk/electromagnetic__gb_1.mp3","us":"media/us/electromagnetic__us_1.mp3"},"examples":[{"en":"an electromagnetic wave/field","cn":"电磁波/场"},{"en":"electromagnetic waves","cn":"电磁波"}]},"elevator":{"media":{"uk":"media/uk/elevator__gb_1.mp3","us":"media/us/elevator__us_1.mp3"},"oxford":{"phon":"ˈelɪveɪtə(r)","pos":"noun","senses":[{"en":"a machine that carries people or goods up and down to different levels in a building or a mine","cn":"电梯；升降机","lab":"North American English","ex":{"en":"It's on the fifth floor, so we'd better take the elevator.","cn":"那是在六楼，我们最好乘电梯。"}},{"en":"a tall building used to store grain and that contains equipment to move it","cn":"（有谷物升运器的）谷仓，粮仓","lab":"North American English","ex":{"en":"In the harbour a giant elevator stores prairie grain.","cn":"港口里有一个巨大的谷仓塔储存着草原谷物。"}},{"en":"a part in the tail of an aircraft that is moved to make it go up and down","cn":"（航空器的）升降舵"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"电梯","en":"An elevator is a device that carries people up and down inside buildings."}]},"examples":[{"en":"It's on the fifth floor, so we'd better take the elevator.","cn":"那是在六楼上，我们最好乘电梯。"},{"en":"We’ll have to take the elevator.","cn":"我们只好坐电梯了。"}]},"electricity":{"media":{"uk":"media/uk/electricity__gb_1.mp3","us":"media/us/electricity__us_1.mp3"},"oxford":{"phon":"ɪˌlekˈtrɪsəti","pos":"noun","senses":[{"en":"a form of energy from charged elementary particles, usually supplied as electric current through cables, wires, etc. for lighting, heating, driving machines, etc.","cn":"电；电能","g":"[uncountable]","ex":{"en":"materials that conduct electricity","cn":"导电材料"}},{"en":"a feeling of great emotion, excitement, etc.","cn":"强烈的感情；激动；兴奋","g":"[uncountable, singular]"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"电;电力","en":"Electricity is a form of energy that can be carried by wires and is used for heating and lighting, and to provide power for machines.","ex":{"en":"We moved into a cabin with electricity but no running water","cn":"我们搬进一栋通了电但没有自来水的小屋。"}}]},"examples":[{"en":"The electricity is off (= there is no electric power supply).","cn":"停电了。"},{"en":"a waste of electricity","cn":"浪费电"}]},"elite":{"media":{"uk":"media/uk/elite__gb_1.mp3","us":"media/us/elite__us_1.mp3"},"oxford":{"phon":"eɪˈliːt","pos":"adjective","senses":[{"en":"belonging to a group of people in society that is small in number but powerful and with a lot of influence, because they are rich, intelligent, etc.","cn":"精英：属于社会上人数不多，但权势很大，影响力很大的群体，因为他们很有钱，很有智慧等等。","ex":{"en":"an elite group of senior officials","cn":"一群位高权重的高官"}},{"en":"having or showing the greatest ability at the highest level of competition","cn":"精英：在最高水平的比赛中拥有或表现出最大的能力","ex":{"en":"an elite athlete/swimmer/runner","cn":"运动／游泳／赛跑健将"}},{"en":"a small group of people in a society, etc. who are powerful and have a lot of influence, because they are rich, intelligent, etc.","cn":"上层集团；（统称）掌权人物，社会精英","ex":{"en":"a member of the ruling/intellectual elite","cn":"上层统治集团的成员；知识界的精英"},"pos":"noun"},{"en":"a group of people with the greatest ability at the highest level of competition, especially in sport","cn":"（体育比赛）精英","ex":{"en":"The club has returned to the elite of European football.","cn":"这家俱乐部已回归欧洲足球精英圈。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"精英;杰出人物","en":"You can refer to the most powerful, rich, or talented people within a particular group, place, or society as the elite .","ex":{"en":"...a government comprised mainly of the elite","cn":"主要由精英组成的政府"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"精英的;精锐的;最优秀的","en":"Elite people or organizations are considered to be the best of their kind.","ex":{"en":"...the elite troops of the President's bodyguard.","cn":"精锐的总统卫队"}}]},"examples":[{"en":"In these countries, only the elite can afford an education for their children.","cn":"在这些国家里，只有上层人士才供得起子女上学。"},{"en":"Public opinion is influenced by the small elite who control the media.","cn":"舆论为少数控制着新闻媒介的上层人士所左右。"}]},"electrify":{"oxford":{"phon":"ɪˈlektrɪfaɪ","pos":"verb","senses":[{"en":"to make something work by using electricity; to pass an electrical current through something","cn":"使电气化；使通电；使带电","g":"[usually passive]","ex":{"en":"The railway line was electrified in the 1950s.","cn":"这条铁路线在 20 世纪 50 年代实现了电气化。"}},{"en":"to make somebody feel very excited and enthusiastic about something","cn":"使激动；使兴奋","ex":{"en":"Her performance electrified the audience.","cn":"她的表演使观众兴奋不已。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"使极为兴奋;使激动不已;使震惊","en":"If people are electrified by an event or experience, it makes them feel very excited and surprised.","ex":{"en":"The world was electrified by his courage and resistance.","cn":"世人为他的勇气和反抗精神震惊不已。"}},{"pos":"VERB 动词","cn":"使电气化;使通电","en":"When a railway system or railway line is electrified, electric cables are put over the tracks, or electric rails are put beside them, so that the trains can be powered by electricity.","ex":{"en":"The west-coast line was electrified as long ago as 1974.","cn":"西海岸铁路线早在1974年就实现了电气化。"}}]},"media":{"uk":"media/uk/electrify__gb_1.mp3","us":"media/us/electrify__us_1.mp3"},"examples":[{"en":"The railway line was electrified in the 1950s.","cn":"这条铁路线在 20 世纪 50 年代就以电力推动了。"},{"en":"He had all the fences around his home electrified.","cn":"他把房子周围的铁丝网都通了电。"}]},"elderly":{"media":{"uk":"media/uk/elderly__gb_1.mp3","us":"media/us/elderly__us_1.mp3"},"oxford":{"phon":"ˈeldəli","pos":"adjective","senses":[{"en":"used as a polite word for ‘old’","cn":"年纪较大的，上了年纪的（婉辞，与 old 同义）","ex":{"en":"an elderly man/woman/lady","cn":"年长的男人／女人／女士"}},{"en":"people who are old","cn":"老人；上了年纪的人","g":"[plural]","ex":{"en":"Children and the elderly are those most at risk from the infection.","cn":"儿童和老年人是最容易受到感染的人群。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"年长的;上年纪的","en":"You use elderly as a polite way of saying that someone is old.","ex":{"en":"...an elderly couple","cn":"老夫妇"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"老式的;老掉牙的","en":"If you describe an object as elderly, you are referring, often in a humorous way, to the fact that it is rather old or old-fashioned and not as good or efficient as a new one would be. →see usage note at:","ex":{"en":"Some of those artillery pieces look a little elderly.","cn":"那些大炮中有些看起来有点老掉牙了。"}}]},"examples":[{"en":"an elderly couple","cn":"一对老年夫妇"},{"en":"elderly relatives","cn":"年老的亲戚"}]},"elsewhere":{"media":{"uk":"media/uk/elsewhere__gb_1.mp3","us":"media/us/elsewhere__us_1.mp3"},"oxford":{"phon":"ˌelsˈweə(r)","pos":"adverb","senses":[{"en":"in, at or to another place or other places","cn":"在（或去、到）别处","ex":{"en":"Dissatisfied customers will look elsewhere.","cn":"不满意的客户会另寻他处。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"在别处;去别处","en":"Elsewhere means in other places or to another place.","ex":{"en":"Almost 80 percent of the state's residents were born elsewhere","cn":"该州居民中几乎有80%出生在异地。"}}]},"examples":[{"en":"Our favourite restaurant was closed, so we had to go elsewhere.","cn":"我们最喜欢的餐馆已关门了，所以我们只好到别处去。"},{"en":"The answer to the problem must be sought elsewhere.","cn":"这个问题的答案必须在别处寻找。"}]},"elections":{"oxford":{"phon":"ɪˈlekʃn","pos":"noun","senses":[{"en":"the process of choosing a person or a group of people for a position, especially a political position, by voting","cn":"选举，推选（尤指从政）"},{"en":"the fact of having been chosen by election","cn":"当选"}]},"media":{"uk":"media/uk/election__gb_1.mp3","us":"media/us/election__us_1.mp3"}},"electrification":{"media":{"uk":"media/uk/electrification__gb_1.mp3","us":"media/us/electrification__us_1.mp3"},"oxford":{"phon":"ɪˌlektrɪfɪˈkeɪʃn","pos":"noun","senses":[{"en":"the process of changing something so that it works by electricity","cn":"电气化","ex":{"en":"the electrification of the railway line from Manchester to Preston","cn":"从曼彻斯特到普雷斯顿的铁路线电气化"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"通电;供电","en":"The electrification of a house, town, or area is the connecting of that place with a supply of electricity.","ex":{"en":"...rural electrification.","cn":"农村供电"}}]},"examples":[{"en":"She would sit at the piano and sing, electrifying us all.","cn":""},{"en":"The west coast main line has been electrified.","cn":""}]},"electric":{"media":{"uk":"media/uk/electric__gb_1.mp3","us":"media/us/electric__us_1.mp3","img":["media/ldoce/img/guitar.jpg"]},"oxford":{"phon":"ɪˈlektrɪk","pos":"adjective","senses":[{"en":"connected with electricity; using, produced by or producing electricity","cn":"电的；用电的；电动的；发电的","g":"[usually before noun]","ex":{"en":"an electric car/vehicle","cn":"电动汽车"}},{"en":"full of excitement; making people excited","cn":"充满刺激的；令人激动的","ex":{"en":"The atmosphere was electric.","cn":"气氛很热烈。"}},{"en":"the system of electrical wires in a house, car or machine","cn":"（房屋、汽车或机器的）电力系统，电路","g":"[plural]","lab":"British English, informal，，","ex":{"en":"There's a problem with the electrics.","cn":"电路有故障。"},"pos":"noun"},{"en":"used to refer to the supply of electricity to a building","cn":"供电","g":"[uncountable]","lab":"informal","ex":{"en":"The electric will be off tomorrow.","cn":"明天停电。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"用电的;电动的","en":"An electric device or machine works by means of electricity, rather than using some other source of power.","ex":{"en":"...her electric guitar.","cn":"她的电吉他"}},{"pos":"ADJ 形容词","cn":"电的;由电产生的","en":"An electric current, voltage, or charge is one that is produced by electricity."},{"pos":"ADJ 形容词","cn":"通电的;导电的","en":"Electric plugs, sockets, or power lines are designed to carry electricity."},{"pos":"ADJ 形容词","cn":"电的;供电的","en":"Electric is used to refer to the supply of electricity.","ex":{"en":"An average electric bill might go up $2 or $3 per month","cn":"每月电费可能会平均增加两三美元。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"扣人心弦的;紧张刺激的","en":"If you describe the atmosphere of a place or event as electric, you mean that people are in a state of great excitement.","ex":{"en":"The mood in the hall was electric.","cn":"大厅里的气氛非常紧张。"}}]},"examples":[{"en":"an electric plug/socket/switch (= that carries electricity)","cn":"电源插头/插座/开关"},{"en":"I've paid the electric (= the bill for the supply of electricity).","cn":"我已经付电费了。"}]},"electron":{"media":{"uk":"media/uk/electron__gb_1.mp3","us":"media/us/electron__us_1.mp3"},"oxford":{"phon":"ɪˈlektrɒn","pos":"noun","senses":[{"en":"a very small piece of matter (= a substance) with a negative electric charge, found in all atoms","cn":"电子"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"电子","en":"An electron is a tiny particle of matter that is smaller than an atom and has a negative electrical charge."}]}},"eligible":{"media":{"uk":"media/uk/eligible__gb_1.mp3","us":"media/us/eligible__us_1.mp3"},"oxford":{"phon":"ˈelɪdʒəbl","pos":"adjective","senses":[{"en":"a person who is eligible for something or to do something, is able to have or do it because they have the right qualifications, are the right age, etc.","cn":"有资格的；合格的；具备条件的","ex":{"en":"Only those over 70 are eligible for the special payment.","cn":"只有 70 岁以上的人才有资格领取这项专款。"}},{"en":"an eligible young man or woman is thought to be a good choice as a husband/wife, usually because they are rich or attractive","cn":"（指作为结婚对象）合意的，合适的，中意的"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有资格的;符合条件的;有能力的","en":"Someone who is eligible to do something is qualified or able to do it, for example because they are old enough.","ex":{"en":"Almost half the population are eligible to vote in today's election","cn":"大约有一半人有资格参加今天的选举投票。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（作为结婚对象）合适的，中意的","en":"An eligible man or woman is not yet married and is thought by many people to be a suitable partner.","ex":{"en":"He's the most eligible bachelor in Japan.","cn":"他是日本最为抢手的单身汉。"}}]},"examples":[{"en":"Only those over 70 are eligible for the special payment.","cn":"只有 70 岁以上的人才有资格领取这项专款。"},{"en":"When are you eligible to vote in your country?","cn":"在你们国家几岁才有资格投票选举呢？"}]},"elementary":{"media":{"uk":"media/uk/elementary__gb_1.mp3","us":"media/us/elementary__us_1.mp3"},"oxford":{"phon":"ˌelɪˈmentri","pos":"adjective","senses":[{"en":"in or connected with the first stages of a course of study","cn":"初级的；基础的","ex":{"en":"an elementary English course","cn":"基础英语课程"}},{"en":"of the most basic kind","cn":"基本的","ex":{"en":"It's an elementary law of economics: the scarcer the commodity, the higher the price.","cn":"这是经济学的基本法则：商品越稀缺，价格越高。"}},{"en":"very simple and easy","cn":"简单的；容易的","ex":{"en":"elementary questions","cn":"简单的问题"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"简单的;基本的","en":"Something that is elementary is very simple and basic.","ex":{"en":"...elementary computer skills.","cn":"基本计算机技能"}}]},"examples":[{"en":"an elementary English course","cn":"基础英语课程"},{"en":"at an elementary level","cn":"处于初级水平"}]},"electronically":{"media":{"uk":"media/uk/electronically__gb_1.mp3","us":"media/us/electronically__us_1.mp3"},"oxford":{"phon":"ɪˌlekˈtrɒnɪkli","pos":"adverb","senses":[{"en":"in an electronic way, or using a device that works in an electronic way","cn":"用电子方法；用电子装置","ex":{"en":"to process data electronically (= using a computer)","cn":"进行电子数据处理"}}]},"examples":[{"en":"to process data electronically (= using a computer)","cn":"进行电子数据处理"},{"en":"an electronic organizer (= a small piece of electronic equipment that you can use to record addresses, phone numbers etc )","cn":""}]},"electrical":{"media":{"uk":"media/uk/electrical__gb_1.mp3","us":"media/us/electrical__us_1.mp3"},"oxford":{"phon":"ɪˈlektrɪkl","pos":"adjective","senses":[{"en":"connected with electricity; using or producing electricity","cn":"电的；用电的；发电的","ex":{"en":"an electrical fault in the engine","cn":"发动机的电路故障"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"用电的;电动的","en":"Electrical goods, equipment, or appliances work by means of electricity.","ex":{"en":"...shipments of electrical equipment.","cn":"电气设备的装运"}},{"pos":"ADJ 形容词","cn":"供电的;用电的","en":"Electrical systems or parts supply or use electricity."},{"pos":"ADJ 形容词","cn":"电能的;充电的","en":"Electrical energy is energy in the form of electricity."},{"pos":"ADJ 形容词","cn":"制造电气设备的;供电的","en":"Electrical industries, engineers, or workers are involved in the production and supply of electricity or electrical goods."}]},"examples":[{"en":"an electrical fault in the engine","cn":"发动机的电力故障"},{"en":"a car with electrically operated windows","cn":"带电动窗的汽车"}]},"elaborately":{"oxford":{"phon":"ɪˈlæbərətli","pos":"adverb","senses":[{"en":"in a very complicated and detailed way; in a carefully prepared and organized way","cn":"复杂地；周详充分地 ；精心地；精美地","ex":{"en":"an elaborately decorated room","cn":"精心装饰的房间"}}]},"media":{"uk":"media/uk/elaborately__gb_1.mp3","us":"media/us/elaborately__us_1.mp3"},"examples":[{"en":"an elaborately decorated room","cn":"精心装饰的房间"},{"en":"pure silks embroidered with elaborate patterns","cn":""}]},"elation":{"media":{"uk":"media/uk/elation__gb_1.mp3","us":"media/us/elation__us_1.mp3"},"oxford":{"phon":"ɪˈleɪʃn","pos":"noun","senses":[{"en":"a feeling of great happiness and excitement","cn":"兴高采烈；欢欣鼓舞；喜气洋洋","ex":{"en":"She felt a great sense of elation as she started on the journey.","cn":"当她踏上旅程时，她感到非常高兴。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"得意洋洋;兴高采烈","en":"Elation is a feeling of great happiness and excitement about something that has happened.","ex":{"en":"His supporters have reacted to the news with elation.","cn":"他的支持者听到那条消息后兴高采烈。"}}]}},"elusive":{"media":{"uk":"media/uk/elusive__gb_1.mp3","us":"media/us/elusive__us_1.mp3"},"oxford":{"phon":"ɪˈluːsɪv","pos":"adjective","senses":[{"en":"difficult to find, define or achieve","cn":"难找的；难以解释的；难以达到的","ex":{"en":"Eric, as elusive as ever, was nowhere to be found.","cn":"埃里克总是这样神出鬼没，哪儿也找不着。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"难以得到的;难以描述的;想不起来的；难以实现的","en":"Something or someone that is elusive is difficult to find, describe, remember, or achieve.","ex":{"en":"In London late-night taxis are elusive and far from cheap.","cn":"在伦敦，深夜时难以打到出租车，而且车费非常贵。"}}]},"examples":[{"en":"Eric, as elusive as ever, was nowhere to be found.","cn":"埃里克神出鬼没，哪儿也找不着。"},{"en":"A solution to the problem of toxic waste is proving elusive.","cn":"有毒废料这个问题日见难以解决。"}]},"element":{"media":{"uk":"media/uk/element__gb_1.mp3","us":"media/us/element__us_1.mp3"},"oxford":{"phon":"ˈelɪmənt","pos":"noun","senses":[{"en":"a necessary or typical part of something; one of several parts that something contains","cn":"要素；因素；典型部分","g":"[countable]","sc":"part/amount","ex":{"en":"There are three important elements to consider.","cn":"有三个重要因素需要考虑。"}},{"en":"a small amount of a quality or feeling","cn":"少量；有点；有些","g":"[countable, usually singular]","sc":"part/amount","ex":{"en":"We need to preserve the element of surprise.","cn":"我们得保留一些使人感到意外的东西。"}},{"en":"a simple chemical substance that consists of atoms of only one type and cannot be split by chemical means into a simpler substance. Gold, oxygen and carbon are all elements.","cn":"元素（如金、氧、碳）","g":"[countable]","sc":"chemistry","ex":{"en":"All chemical substances, whether elements, compounds or mixtures, are made up of three types of particles.","cn":"所有化学物质，无论是元素、化合物还是混合物，都由三种粒子组成。"}},{"en":"one of the four substances: earth, air, fire and water, which people used to believe everything else was made of","cn":"要素（旧时认为土、空气、火和水是构成一切物质的四大要素）","g":"[countable]","sc":"earth/air/fire/water"},{"en":"the weather, especially bad weather","cn":"（尤指恶劣的）天气","g":"[plural]","sc":"weather","ex":{"en":"Are we going to brave the elements and go for a walk?","cn":"我们要冒着风雨去散步吗？"}},{"en":"the basic principles of a subject that you have to learn first","cn":"（学科的）基本原理，基础，纲要","g":"[plural]","sc":"basic principles","ex":{"en":"He taught me the elements of map-reading.","cn":"他教我看地图的基本方法。"}},{"en":"a group of people who form a part of a larger group or society","cn":"（大团体或社会中的）一组，一群，一伙","g":"[countable, usually plural]","sc":"group of people","ex":{"en":"moderate/radical elements within the party","cn":"党内的温和派／激进派"}},{"en":"a natural or suitable environment, especially for an animal","cn":"（尤指动物的）自然环境，适宜的环境","g":"[countable, usually singular]","sc":"environment","ex":{"en":"Water is a fish's natural element.","cn":"水是鱼的天然生活环境。"}},{"en":"the part of a piece of electrical equipment that gives out heat","cn":"电热元件；电热丝","g":"[countable]","sc":"electrical part","ex":{"en":"The water heater has electric heating elements submerged in a storage tank.","cn":"热水器的电加热元件浸没在储水箱中。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"成分;组成部分","en":"The different elements of something are the different parts it contains.","ex":{"en":"The exchange of prisoners of war was one of the key elements of the UN's peace plan.","cn":"交换战俘是联合国和平计划的一个重要部分。"}},{"pos":"N-COUNT 可数名词","cn":"要素；基本部分","en":"A particular element of a situation, activity, or process is an important quality or feature that it has or needs.","ex":{"en":"Fitness has now become an important element in our lives.","cn":"现在健康已经成为我们生活中的一个要素。"}},{"pos":"N-COUNT 可数名词","cn":"（社会或组织内部具有相同目标、信仰或习惯的）一群人，一组人，分子","en":"When you talk about elements within a society or organization, you are referring to groups of people who have similar aims, beliefs, or habits.","ex":{"en":"...criminal elements within the security forces.","cn":"安保部队中的犯罪分子"}},{"pos":"N-COUNT 可数名词","cn":"些许;一些","en":"If something has an element of a particular quality or emotion, it has a certain amount of this quality or emotion.","ex":{"en":"These reports clearly contain elements of propaganda.","cn":"这些报告明显带有一些宣传的意味。"}},{"pos":"N-COUNT 可数名词","cn":"（化学中的）元素","en":"An element is a substance such as gold, oxygen, or carbon that consists of only one type of atom."},{"pos":"N-COUNT 可数名词","cn":"（电炉、热水器等的）电热元件，电热丝","en":"The element in an electric fire or water heater is the metal part which changes the electric current into heat.","ex":{"en":"With its unique heating element it makes perfect coffee.","cn":"其独特的电热元件使它能够煮出非常美味的咖啡。"}},{"pos":"N-PLURAL 复数名词","cn":"天气；（尤指）风雨","en":"You can refer to the weather, especially wind and rain, as the elements .","ex":{"en":"The area where most refugees are waiting is exposed to the elements.","cn":"大多数难民等待救济的地方都不能挡风遮雨。"}},{"pos":"PHRASE 短语","cn":"自在;适得其所;如鱼得水","en":"If you say that someone is in their element, you mean that they are in a situation they enjoy.","ex":{"en":"My stepmother was in her element, organizing everything","cn":"我的继母得心应手地料理着一切。"}}]},"examples":[{"en":"Cost was a key element in our decision.","cn":"成本是我们决策时考虑的一个重要因素。"},{"en":"Customer relations is an important element of the job.","cn":"与客户的关系是这个工作的重要部分。"}]},"elegant":{"media":{"uk":"media/uk/elegant__gb_1.mp3","us":"media/us/elegant__us_1.mp3"},"oxford":{"phon":"ˈelɪɡənt","pos":"adjective","senses":[{"en":"attractive and showing a good sense of style","cn":"优美的；文雅的","ex":{"en":"She was tall and elegant.","cn":"她身材修长，优雅大方。"}},{"en":"attractive and designed well","cn":"漂亮雅致的；陈设讲究的；精美的","ex":{"en":"an elegant dress","cn":"高雅的连衣裙"}},{"en":"clever but simple","cn":"简练的；简洁的；简明的","ex":{"en":"an elegant solution to the problem","cn":"解决这个问题的简要方法"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人或物）典雅的，雅致的，优美的","en":"If you describe a person or thing as elegant, you mean that they are pleasing and graceful in appearance or style.","ex":{"en":"Patricia looked beautiful and elegant as always.","cn":"帕特里夏一如既往地美丽优雅。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（文字、想法、计划等）简洁的，简练的，巧妙的","en":"If you describe a piece of writing, an idea, or a plan as elegant, you mean that it is simple, clear, and clever.","ex":{"en":"The document impressed me with its elegant simplicity.","cn":"那份文件的简洁明了给我留下了深刻印象。"}}]},"examples":[{"en":"She dresses with casual elegance.","cn":"她的穿着随意而不失雅致。"},{"en":"She was tall and elegant.","cn":"她身材修长，优雅大方。"}]},"eleven":{"media":{"uk":"media/uk/eleven__gb_1.mp3","us":"media/us/eleven__us_1.mp3"},"oxford":{"phon":"ɪˈlevn","pos":"","senses":[{"en":"11","cn":"十一","ex":{"en":"There are only eleven of these rare animals left.","cn":"这些珍稀动物只剩下十一只了。"}},{"en":"a team of eleven players for football (soccer), cricket or hockey","cn":"（足球、板球或曲棍球）十一人队","ex":{"en":"She was chosen for the first eleven.","cn":"她被选派首发上场。"}}]},"collins":{"senses":[{"pos":"NUM 数词","cn":"（数字）11","en":"Eleven is the number 11.","ex":{"en":"...the Princess and her eleven friends.","cn":"公主和她的11位朋友"}}]},"examples":[{"en":"She was chosen for the first eleven.","cn":"她被选派首发上场。"},{"en":"She was sent to jail for eleven months.","cn":"她被判入狱11个月。"}]},"elaborate":{"media":{"uk":"media/uk/elaborate__gb_1.mp3","us":"media/us/elaborate__us_1.mp3"},"oxford":{"phon":"ɪˈlæbərət","pos":"adjective","senses":[{"en":"very complicated and detailed; carefully prepared and organized","cn":"复杂的；详尽的；精心制作的","ex":{"en":"elaborate designs","cn":"精心的设计"}},{"en":"to explain or describe something in a more detailed way","cn":"详尽阐述；详细描述","g":"[intransitive, transitive]","ex":{"en":"He said he was resigning but did not elaborate on his reasons.","cn":"他说他准备辞职但未详细说明原因。"},"pos":"verb"},{"en":"to develop a plan, an idea, etc. and make it complicated or detailed","cn":"详细制订；精心制作","g":"[transitive]","ex":{"en":"In his plays he takes simple traditional tales and elaborates them.","cn":"他在剧本里采用了一些简单的传统故事并加以发挥。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"复杂的","en":"You use elaborate to describe something that is very complex because it has a lot of different parts.","ex":{"en":"...an elaborate research project.","cn":"复杂的研究计划"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（计划、系统、程序等）繁复的，详尽的，过于复杂的","en":"Elaborate plans, systems, and procedures are complicated because they have been planned in very great detail, sometimes too much detail.","ex":{"en":"...elaborate efforts at the highest level to conceal the problem.","cn":"最高层为了隐瞒问题而挖空心思"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（衣服、布料等）精致的，精巧的，制作精美的","en":"Elaborate clothing or material is made with a lot of detailed artistic designs.","ex":{"en":"He is known for his elaborate costumes.","cn":"他以着装精致而闻名。"}},{"pos":"VERB 动词","cn":"精心制作;详细计划;进一步完善","en":"If you elaborate a plan or theory, you develop it by making it more complicated and more effective.","ex":{"en":"His task was to elaborate policies which would make a market economy compatible with a clean environment.","cn":"他的任务是制定详细政策，使得市场经济和清洁环境能够共存。"}},{"pos":"VERB 动词","cn":"详细说明；详尽阐述","en":"If you elaborate on something that has been said, you say more about it, or give more details.","ex":{"en":"A spokesman declined to elaborate on a statement released late yesterday","cn":"发言人拒绝对昨天晚些时候发表的声明详加说明。"}}]},"examples":[{"en":"In his plays he takes simple traditional tales and elaborates them.","cn":"他在剧本里采用了一些简单的传统故事并加以发挥。"},{"en":"He said he was resigning but did not elaborate on his reasons.","cn":"他说他准备辞职但未详细说明原因。"}]},"election":{"media":{"uk":"media/uk/election__gb_1.mp3","us":"media/us/election__us_1.mp3"},"oxford":{"phon":"ɪˈlekʃn","pos":"noun","senses":[{"en":"the process of choosing a person or a group of people for a position, especially a political position, by voting","cn":"选举，推选（尤指从政）","g":"[countable, uncountable]","lab":"especially British English","ex":{"en":"presidential/parliamentary/local elections","cn":"总统／议会／地方选举"}},{"en":"the fact of having been chosen by election","cn":"当选","g":"[uncountable]","ex":{"en":"Her election will mark a new beginning for the country.","cn":"她的当选将标志着这个国家的新开始。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"选举；推举","en":"An election is a process in which people vote to choose a person or group of people to hold an official position.","ex":{"en":"...the first fully free elections for more than fifty years","cn":"50多年来第一次完全自由的选举"}},{"pos":"N-UNCOUNT 不可数名词","cn":"当选；选举获胜","en":"The election of a particular person or group of people is their success in winning an election.","ex":{"en":"...the election of the Labour government in 1964.","cn":"1964年工党政府当选"}}]},"examples":[{"en":"The leader will be chosen by secret ballot.","cn":"领导人将通过无记名投票选举产生。"},{"en":"In America, presidential elections are held every four years.","cn":"美国每四年举行一次总统选举。"}]},"electoral":{"oxford":{"phon":"ɪˈlektərəl","pos":"adjective","senses":[{"en":"connected with elections","cn":"有关选举的","ex":{"en":"electoral systems/reforms","cn":"选举制度／改革"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"与选举有关的;选举的","en":"Electoral is used to describe things that are connected with elections.","ex":{"en":"The Mongolian Democratic Party is campaigning for electoral reform.","cn":"蒙古民主党正发起运动争取选举改革。"}}]},"media":{"uk":"media/uk/electoral__gb_1.mp3","us":"media/us/electoral__us_1.mp3"},"examples":[{"en":"an electorally effective campaign","cn":"富有成效的竞选运动"},{"en":"electoral systems/reforms","cn":"选举制度/改革"}]},"elf":{"oxford":{"phon":"elf","pos":"noun","senses":[{"en":"(in stories) a creature like a small person with pointed ears, who has magic powers","cn":"（故事中的）精灵，小妖精"},{"en":"English as a lingua franca (English used as a shared language of communication between people whose main languages are different)","cn":"作为族际通用语的英语","pos":"abbreviation"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（神话故事中的）小精灵，小妖精","en":"In fairy stories, elves are small magical beings who play tricks on people."}]},"media":{"uk":"media/uk/elf__gb_1.mp3","us":"media/us/elf__us_1.mp3"}},"elbows":{"oxford":{"phon":"ˈelbəʊ","pos":"noun","senses":[{"en":"the joint between the upper and lower parts of the arm where it bends in the middle","cn":"肘；肘部"},{"en":"the part of a piece of clothing that covers the elbow （","cn":"衣服的）肘部"}]}},"elicit":{"media":{"uk":"media/uk/elicit__gb_1.mp3","us":"media/us/elicit__us_1.mp3"},"oxford":{"phon":"ɪˈlɪsɪt","pos":"verb","senses":[{"en":"to get information or a reaction from somebody, often with difficulty","cn":"引出；探出；诱出","ex":{"en":"I could elicit no response from him.","cn":"我从他那里套不出任何反应。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"引起;引出","en":"If you elicit a response or a reaction, you do or say something which makes other people respond or react.","ex":{"en":"Mr Norris said he was hopeful that his request would elicit a positive response","cn":"诺里斯先生说希望他的请求能够引起积极反响。"}},{"pos":"VERB 动词","cn":"探出;套出","en":"If you elicit a piece of information, you get it by asking the right questions.","ex":{"en":"Phone calls elicited no further information.","cn":"几个电话都没有打听到进一步的消息。"}}]},"examples":[{"en":"Her tears elicited great sympathy from her audience.","cn":"她的眼泪博得观众的无限同情。"},{"en":"I could elicit no response from him.","cn":"我从他那里套不出任何反应。"}]},"elbow":{"oxford":{"phon":"ˈelbəʊ","pos":"noun","senses":[{"en":"the joint between the upper and lower parts of the arm where it bends in the middle","cn":"肘；肘部","ex":{"en":"She jabbed him with her elbow.","cn":"她用胳膊肘捅他。"}},{"en":"the part of a piece of clothing that covers the elbow","cn":"（衣服的）肘部","ex":{"en":"The jacket was worn at the elbows.","cn":"这件夹克衫的肘部磨破了。"}},{"en":"a part of a pipe, chimney, etc. where it bends at a sharp angle","cn":"（管子、烟囱等的）弯处，弯头"},{"en":"to push somebody with your elbow, usually in order to get past them","cn":"用肘推；用肘挤","ex":{"en":"She elbowed me out of the way to get to the front of the line.","cn":"她用肘部把我推开朝队伍前面挤。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"肘","en":"Your elbow is the part of your arm where the upper and lower halves of the arm are joined.","ex":{"en":"He slipped and fell, badly bruising an elbow.","cn":"他滑倒了，一只胳膊肘严重擦伤。"}},{"pos":"VERB 动词","cn":"用肘推挤","en":"If you elbow people aside or elbow your way somewhere, you push people with your elbows in order to move somewhere.","ex":{"en":"They also claim that the security team elbowed aside a steward","cn":"他们还声称保安人员将一位乘务员推搡至一边。"}},{"pos":"VERB 动词","cn":"跻身;挤掉;排挤","en":"If someone or something elbows their way somewhere, or elbows other people or things out of the way, they achieve success by being aggressive and determined.","ex":{"en":"Non-state firms gradually elbow aside the inefficient state-owned ones","cn":"非国有企业逐渐挤掉了效率低下的国有企业。"}},{"pos":"","cn":"","en":"to rub elbows with→see: ;"}]},"media":{"uk":"media/uk/elbow__gb_1.mp3","us":"media/us/elbow__us_1.mp3"},"examples":[{"en":"She elbowed me out of the way to get to the front of the line.","cn":"她用肘部把我推开朝队伍前面挤。"},{"en":"The jacket was worn at the elbows.","cn":"这件夹克衫的肘部磨破了。"}]},"elaborates":{"oxford":{"phon":"ɪˈlæbərət","pos":"adjective","senses":[{"en":"very complicated and detailed; carefully prepared and organized","cn":"复杂的；详尽的；精心制作的"},{"en":"to explain or describe sth in a more detailed way","cn":"详尽阐述；详细描述"}]}},"elevators":{"oxford":{"phon":"ˈelɪveɪtə(r)","pos":"noun","senses":[{"en":"a machine that carries people or goods up and down to different levels in a building or a mine","cn":"电梯；升降机"},{"en":"a place for storing large quantities of grain","cn":"谷仓；粮仓"}]}},"elders":{"oxford":{"phon":"ˈeldə(r)","pos":"adjective","senses":[{"en":"older","cn":"年纪较长的"},{"en":"used without a noun immediately after it to show who is the older of two people （","cn":"后面不紧跟名词，指两者中的）较年长者"}]}},"elements":{"oxford":{"phon":"ˈelɪmənt","pos":"noun","senses":[{"en":"a necessary or typical part of sth","cn":"要素；基本部分；典型部分"},{"en":"a small amount of a quality or feeling","cn":"少量；有点；有些"}]}},"elastic":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"松紧带;橡皮筋","en":"Elastic is a rubber material that stretches when you pull it and returns to its original size and shape when you let it go. Elastic is often used in clothes to make them fit tightly, for example round the waist.","ex":{"en":"...a piece of elastic.","cn":"一根松紧带"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有弹性的，有弹力的","en":"Something that is elastic is able to stretch easily and then return to its original size and shape.","ex":{"en":"Beat it until the dough is slightly elastic.","cn":"一直搅打，直至生面团略有弹性。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（想法、计划、政策等）有通融性的，灵活的，能变通的","en":"If ideas, plans, or policies are elastic, they are able to change to suit new circumstances or conditions as they occur.","ex":{"en":"...an elastic interpretation of the rules of boxing","cn":"对拳击规则的灵活解释"}},{"pos":"N-COUNT 可数名词","cn":"同 rubber band","en":"An elastic is a rubber band ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a type of rubber material that can stretch and then return to its usual length or size 〔","cn":"橡皮〕弹力材料"},{"en":"made of elastic","cn":"弹力材料制成的"},{"en":"a material that is elastic can stretch and then go back to its usual length or size","cn":"有弹性的"}]},"vocab":{"pos":"1 adj 2 n 3 n","senses":[{"en":"Elastic is the rubber-based material that resumes its original shape after stretching or compression, and anything described as elastic is flexible."}]},"collocations":{"phrases":["ADJ. loose, tight an old skirt with loose elastic","QUANT. length, piece The trousers are held up by a length of elastic around the waist.","ELASTIC + VERB break, go, snap The elastic in these socks has gone."]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41elastic.mp3","us":"media/ldoce/hwd/ame/c/l3elastic.mp3"},"examples":[{"en":"This skirt needs some new elastic in the waist.","cn":"这条裙子需要换一根松紧腰带。"},{"en":"Our plans are fairly elastic.","cn":"我们的计划有相当大的灵活性。"}],"oxford":{"phon":"ɪˈlæstɪk","pos":"noun","senses":[{"en":"material made with rubber, that can stretch and then return to its original size","cn":"橡皮圈（或带）；松紧带","ex":{"en":"This skirt needs some new elastic in the waist.","cn":"这条裙子需要换一根松紧腰带。"}},{"en":"made with elastic","cn":"橡皮圈（或带）的","ex":{"en":"an elastic headband","cn":"松紧头箍"},"pos":"adjective"},{"en":"able to stretch and return to its original size and shape","cn":"有弹性的；有弹力的","ex":{"en":"elastic materials","cn":"弹性材料"},"pos":"adjective"},{"en":"that can change or be changed","cn":"灵活的；可改变的；可伸缩的","ex":{"en":"The demand for the product is elastic.","cn":"产品的需求是有弹性的。"},"pos":"adjective"}]}},"elated":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"兴高采烈的;得意洋洋的","en":"If you are elated, you are extremely happy and excited because of something that has happened.","ex":{"en":"I was elated that my second heart bypass had been successful","cn":"第二次心脏搭桥手术成功了，我很高兴。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very happy and excited about something that has happened","cn":""},{"en":"to feel extremely happy and confident because you are very successful or because something very good has happened to you","cn":""},{"en":"to be very happy about something good that has happened, especially something that makes you proud of yourself","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you're elated you aren't just happy — you're over the moon, absolutely excited and bursting with pride. Like the way you feel after winning a scholarship to an Ivy league school or mastering a back handspring."}]},"collocations":{"phrases":["VERBS be, feel, look, seem, sound","ADV. very | strangely","PREP. at I felt strangely elated at the news. | by elated by our victory | with elated with his success"]},"media":{"uk":"media/ldoce/hwd/bre/1/elated0205.mp3","us":"media/ldoce/hwd/ame/2/elated.mp3"},"examples":[{"en":"They were elated at the result.","cn":"他们对这一结果感到欢欣鼓舞。"},{"en":"I was elated by the prospect of the new job ahead.","cn":"我为眼前新工作的前景所鼓舞。"}],"oxford":{"phon":"ɪˈleɪtɪd","pos":"adjective","senses":[{"en":"very happy and excited because of something good that has happened, or will happen","cn":"兴高采烈的；欢欣鼓舞的；喜气洋洋的","ex":{"en":"They were elated at the result.","cn":"他们对这一结果感到欢欣鼓舞。"}}]}},"electronics":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（尤指用于无线电、电视和计算机的）电子学，电子技术","en":"Electronics is the technology of using transistors and silicon chips, especially in devices such as radios, televisions, and computers.","ex":{"en":"...Europe's three main electronics companies.","cn":"欧洲三大电子公司"}},{"pos":"N-PLURAL 复数名词","cn":"电子设备;电子仪器","en":"You can refer to electronic devices, or the part of a piece of equipment that consists of electronic devices, as the electronics .","ex":{"en":"All the electronics are housed in a waterproof box.","cn":"所有电子设备都储放在一个防水盒中。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the study or industry of making equipment, such as computers and televisions, that work electronically","cn":"电子学﹔电子工业"},{"en":"electronic equipment","cn":"电子设备"}]},"collocations":{"phrases":["ADJ. high-tech, state-of-the-art | consumer, defence, medical","VERB + ELECTRONICS work in About 45,000 people worked in electronics in Scotland.","ELECTRONICS + NOUN company, firm, giant, group Their firm merged with a Japanese electronics giant. | industry, manufacturer | market, secto"]},"media":{"uk":"media/ldoce/hwd/bre/6/brelasdeelectronics.mp3","us":"media/ldoce/hwd/ame/f/electronics.mp3"},"examples":[{"en":"a fault in the electronics","cn":"电子电路故障"},{"en":"the electronics industry","cn":"电子工业"}],"oxford":{"phon":"ɪˌlekˈtrɒnɪks","pos":"noun","senses":[{"en":"the branch of science and technology that studies electric currents in electronic equipment","cn":"电子学","g":"[uncountable]"},{"en":"the use of electronic technology, especially in developing new equipment","cn":"电子技术的应用","g":"[uncountable]","ex":{"en":"the electronics industry","cn":"电子工业"}},{"en":"the electronic circuits and components (= parts) used in electronic equipment","cn":"电子电路；电子器件","g":"[plural]","ex":{"en":"a fault in the electronics","cn":"电子电路故障"}}]}},"elect":{"collins":{"senses":[{"pos":"VERB 动词","cn":"选举;推选","en":"When people elect someone, they choose that person to represent them, by voting for them.","ex":{"en":"The people of the Philippines have voted to elect a new president","cn":"菲律宾人民已投票选举出了一位新总统。"}},{"pos":"VERB 动词","cn":"选择，决定(做)","en":"If you elect to do something, you choose to do it.","ex":{"en":"Those electing to smoke will be seated at the rear.","cn":"那些想吸烟的人将坐在后排。"}},{"pos":"ADJ 形容词","cn":"已当选但未就任的;候任的","en":"Elect is added after words such as 'president' or 'governor' to indicate that a person has been elected to the post but has not officially started to carry out the duties involved.","ex":{"en":"...the date when the president-elect takes office.","cn":"候任总统就职日"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to show which person or party you want, or whether you support a plan, by marking a piece of paper, raising your hand etc","cn":""},{"en":"to choose a leader, representative, or government by voting, so that they become the new leader, representative etc","cn":""},{"en":"if a country or voters go to the polls, they vote in an election – used especially in news reports","cn":""}]},"vocab":{"pos":"v adj n","senses":[{"en":"To elect is to choose. A group of citizens may elect the next president, or you may just elect to stay home during the blizzard."}]},"collocations":{"phrases":["ADV. annually Members of the council are elected annually. | locally, nationally | democratically, freely, popularly | unanimously | directl","PREP. to She has been elected to Parliament.","PHRASES be/get elected What changes will he make if he gets elected? | be declared elected Any candidate with more than half the votes shall"]},"media":{"uk":"media/ldoce/hwd/bre/1/elect_adj0205.mp3","us":"media/ldoce/hwd/ame/7/elect1.mp3"},"examples":[{"en":"She became the first black woman to be elected to the Senate.","cn":"她成为第一个被选进参议院的黑人妇女。"},{"en":"Increasing numbers of people elect to work from home nowadays.","cn":"现在越来越多的人选择在家工作。"}],"oxford":{"phon":"ɪˈlekt","pos":"verb","senses":[{"en":"to choose somebody to do a particular job by voting for them","cn":"选举；推选","lab":"especially North American English","ex":{"en":"Voters will elect a new president on 30 March next year.","cn":"选民将于明年 3 月 30 日选出新总统。"}},{"en":"to choose to do something","cn":"选择，决定（做某事）","lab":"formal","ex":{"en":"Increasing numbers of people elect to work from home nowadays.","cn":"现在越来越多的人选择在家工作。"}},{"en":"used to show that somebody has been chosen for a job, but is not yet doing that job","cn":"当选而尚未就职的；候任的","g":"[after noun]","ex":{"en":"the president-elect","cn":"候任总统"},"pos":"adjective"},{"en":"people who have been chosen to be saved from punishment after death","cn":"上帝的选民","g":"[plural]","lab":"religion","pos":"adjective"},{"en":"people who have been chosen for honour or knowledge","cn":"上帝的选民","g":"[plural]","lab":"formal","ex":{"en":"He was convinced he was among the elect, the wise, those who would shape the future.","cn":"他坚信自己是选民、智者、将塑造未来的人之一。"},"pos":"adjective"}]}},"electorate":{"collins":{"senses":[{"pos":"N-COUNT-COLL 可数集合名词","cn":"（一国或一地区的）全体选民","en":"The electorate of a country or area is all the people in it who have the right to vote in an election.","ex":{"en":"He has the backing of almost a quarter of the electorate.","cn":"他得到了几乎1/4选民的支持。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who votes in a political election","cn":""},{"en":"all the people who can vote in a country or area","cn":""},{"en":"all the people in a country who have the right to vote 〔","cn":"一个国家的〕全体选民"}]},"vocab":{"pos":"n","senses":[{"en":"An electorate is a body of people allowed to vote in an election. In the United States, when you turn eighteen, you may join the electorate and help choose a president."}]},"collocations":{"phrases":["ADJ. registered | total | local, national | mass The rise of a mass electorate forced politicians to try and broaden their appeal. | middle-","ELECTORATE + VERB choose sb, elect sb, go to the polls, vote the representative chosen by the electorate","PHRASES the electorate as a whole/the electorate at large the need to appeal to the electorate at large"]},"media":{"uk":"media/ldoce/hwd/bre/9/electorate0205.mp3","us":"media/ldoce/hwd/ame/e/electorate.mp3"},"examples":[{"en":"Only 60% of the electorate voted in the last election.","cn":"上次选举只有 60% 的选民参加了投票。"},{"en":"A majority of the electorate oppose the law.","cn":"大多数选民反对这项法规。"}],"oxford":{"phon":"ɪˈlektərət","pos":"noun","senses":[{"en":"the people in a country or an area who have the right to vote, thought of as a group","cn":"（一国或一地区的）全体选民","g":"[countable + singular or plural verb]","lab":"especially North American English","ex":{"en":"Only 60 per cent of the electorate voted in the last election.","cn":"上次选举只有 60% 的选民参加了投票。"}},{"en":"a district that elects its own representative to parliament","cn":"（选举议会议员的）选区","g":"[countable]","lab":"Australian English, New Zealand English，，"}]}},"elector":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"有选举权的人;选民","en":"An elector is a person who has the right to vote in an election."},{"pos":"N-COUNT 可数名词","cn":"选举团成员","en":"An elector is a member of the electoral college. People vote for electors in each state to represent them in the presidential elections."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who has the right to vote in an election","cn":"选民﹐有选举权的人"}]},"collocations":{"phrases":["ADJ. eligible | registered","ELECTOR + VERB choose sb, vote (for sb) Not all the registered electors actually voted.","PHRASES the register of electors If your name is not on the register of electors, you will not be able to vote."]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41elector.mp3","us":"media/ldoce/hwd/ame/4/elector.mp3"},"examples":[{"en":"Over 36% of electors did not vote at all.","cn":"超过36%的选民放弃了投票。"}],"oxford":{"phon":"ɪˈlektə(r)","pos":"noun","senses":[{"en":"a person who has the right to vote in an election","cn":"有选举权的人；选民","ex":{"en":"If your name is not on the register of electors, you will not be able to vote.","cn":"如果名字不在选民登记簿上，你就无权投票。"}},{"en":"a member of the Electoral College","cn":"总统选举团成员"}]}},"electrician":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"电工;电气技师","en":"An electrician is a person whose job is to install and repair electrical equipment."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone whose job is to connect or repair electrical wires or equipment","cn":"电工﹐电力[电气]技师"}]},"collocations":{"phrases":["ADJ. apprentice, qualified","VERB + ELECTRICIAN call in We need to call in an electrician to sort out the wiring.","ELECTRICIAN + VERB rewire sth, wire sth You'll need a qualified electrician to rewire your house. • Note at JOB"]},"media":{"uk":"media/ldoce/hwd/bre/f/electrician0205.mp3","us":"media/ldoce/hwd/ame/7/electrician.mp3"},"oxford":{"phon":"ɪˌlekˈtrɪʃn","pos":"noun","senses":[{"en":"a person whose job is to connect, repair, etc. electrical equipment","cn":"电工；电气技师","ex":{"en":"We need to call in an electrician to sort out the wiring.","cn":"我们需要叫电工来安排线路。"}}]}},"eloquent":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（言辞、文字等）表达生动的，有说服力的","en":"Speech or writing that is eloquent is well expressed and effective in persuading people.","ex":{"en":"I heard him make a very eloquent speech at that dinner.","cn":"在那次晚宴上，我听到他作了一番非常有说服力的陈词。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"雄辩的;口才流利的;能言善辩的","en":"A person who is eloquent is good at speaking and able to persuade people.","ex":{"en":"He was eloquent about his love of books.","cn":"他说起自己对书的喜爱来就会停不住嘴。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a talkative person likes to talk a lot – also used about people’s moods","cn":""},{"en":"liking to talk a lot in a friendly way – a rather informal use","cn":""},{"en":"able to talk easily and effectively about things, especially difficult subjects","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"When you're eloquent , you have a way with words. An eloquent speaker expresses herself clearly and powerfully. Even though eloquent usually describes oral speech, it can also be used to describe powerful writing."}]},"collocations":{"phrases":["VERBS be | become, grow, wax He waxed eloquent about her talents as an actress.","ADV. extremely, very a very eloquent speaker | quite","PREP. about, on He grew quite eloquent on the subject."]},"media":{"uk":"media/ldoce/hwd/bre/8/eloquent0205.mp3","us":"media/ldoce/hwd/ame/c/eloquent.mp3"},"examples":[{"en":"His face expressed his grief more eloquently than any words.","cn":"他那张脸比任何言语都更清楚地表达了他的忧伤。"},{"en":"She spoke eloquently on the subject.","cn":"她讲起这个题目来滔滔不绝。"}],"oxford":{"phon":"ˈeləkwənt","pos":"adjective","senses":[{"en":"able to use language and express your opinions well, especially when you are speaking in public","cn":"雄辩的；有口才的；流利的","ex":{"en":"an eloquent speech/speaker","cn":"雄辩的演讲／演讲人"}},{"en":"able to express a feeling","cn":"传神的","ex":{"en":"His eyes were eloquent.","cn":"他的眼睛很传神。"}}]}}});
